mapper.select:
SELECT T.INTG_INTERFACE_TRANS_ID , T.SCHEDULE_CODE , T.IF_CODE , COALESCE(I.IF_NAME, T.IF_CODE) AS IF_NAME , T.DIVISION_CODE , T.TOTAL_ROWS , TO_CHAR(T.START_TIME, 'YYYY-MM-DD HH24:MI:SS') AS START_TIME , TO_CHAR(T.TRANS_DATE, 'YYYY-MM-DD HH24:MI:SS') AS TRANS_DATE , T.TRANS_STATUS , CASE T.TRANS_STATUS WHEN '0' THEN '진행중' WHEN '1' THEN '성공' WHEN '2' THEN '에러' ELSE T.TRANS_STATUS END AS TRANS_STATUS_NAME , T.STATUS , CASE T.STATUS WHEN 'R' THEN '등록' WHEN 'C' THEN '취소' WHEN 'S' THEN '제출' ELSE T.STATUS END AS STATUS_NAME , T.BATCH_STATUS , CASE T.BATCH_STATUS WHEN 'N' THEN '미처리' WHEN 'F' THEN '완료' WHEN 'E' THEN '오류' ELSE T.BATCH_STATUS END AS BATCH_STATUS_NAME , T.ERROR_YN , T.ERROR_MESSAGE , T.IF_PARAM , T.GROUP_ID , T.ORG_ID , T.INTERFACE_ID , T.INTERFACE_TYPE FROM INTG_INTERFACE_TRANS T LEFT JOIN INTERFACE_ITEM_MST I ON I.IF_CODE = T.IF_CODE AND I.COMPANY_CODE = T.COMPANY_CODE WHERE T.COMPANY_CODE = #{company_code}
AND T.SCHEDULE_CODE = #{selected_schedule_code}
AND T.TRANS_DATE >= TO_DATE(#{from_date}, 'YYYYMMDD')
AND T.TRANS_DATE < TO_DATE(#{to_date}, 'YYYYMMDD') + INTERVAL '1 day'
AND T.TRANS_STATUS = #{trans_status}
AND T.IF_CODE ILIKE CONCAT('%', #{search_keyword}, '%')
AND I.IF_NAME ILIKE CONCAT('%', #{search_keyword}, '%')
AND T.INTERFACE_ID ILIKE CONCAT('%', #{search_keyword}, '%')
ORDER BY T.TRANS_DATE DESC, T.INTG_INTERFACE_TRANS_ID DESC

SELECT D.*
  FROM INTG_INTERFACE_TRANS_DTL D
 WHERE D.INTG_INTERFACE_TRANS_ID = CAST(#{selected_trans_id} AS BIGINT)
   AND D.COMPANY_CODE = #{company_code}

   AND D.ERROR_YN = #{error_yn}

 ORDER BY D.CURRENT_ROW, D.INTG_INTERFACE_ID
